export default async function (e) {
    // 1. Only intercept requests targeting the 'copilot' action
    if (e.data.slug !== 'copilot') {
        return e.data;
    }

    const userPrompt = e?.data?.vars?.prompt;
    if (!userPrompt) {
        return e.data;
    }

    // 2. Determine User Identity & Rate Limit Quota (10 reqs / 10 min for Guest, 15 reqs / 10 min for Auth)
    const isAuth = !!e.auth;
    console.log(JSON.stringify(e.auth))
    const limit = isAuth ? 15 : 10;
    const windowMins = 10;
    const windowMs = windowMins * 60 * 1000;
    const windowIdx = Math.floor(Date.now() / windowMs);

    let identifier = '';
    if (isAuth && e.auth.id) {
        identifier = 'auth_user_' + e.auth.id;
    } else {
        const anonSession = e?.data?.vars?.sessionId || 'unknown_guest';
        identifier = 'anon_session_' + anonSession;
    }

    const cacheKey = `copilot_rl:${identifier}:${windowIdx}`;

    // 3. Evaluate Rate Limit using $cache
    try {
        const currentCountStr = await $cache.get(cacheKey);
        const currentCount = currentCountStr ? parseInt(currentCountStr, 10) : 0;

        if (currentCount >= limit) {
            console.log(`[RateLimit] Blocked ${identifier}. Reached limit ${currentCount}/${limit} for window ${windowIdx}`);
            throw new Error(`Rate limit exceeded (${currentCount}/${limit} requests used in 10 minutes). Please wait a few minutes before trying again.`);
        }

        // Increment counter in cache
        await $cache.incr(cacheKey, 1);
        console.log(`[RateLimit] Allowed ${identifier}. Request count: ${currentCount + 1}/${limit}`);

    } catch (rlErr) {
        if (rlErr.message && rlErr.message.includes('Rate limit exceeded')) {
            throw rlErr;
        }
        console.log('[RateLimit] Cache evaluation note: ' + rlErr);
    }

    // 4. Perform Semantic Vector Search (RAG)
    console.log("Intercepted Copilot request. Running vector search for: " + userPrompt);

    try {
        const searchLimit = 2;
        const vec = await $ai.embed(userPrompt);
        const searchResults = await $db.records.searchVector("articles", "content", vec, searchLimit);

        let contextString = '';

        if (searchResults && searchResults.length > 0) {
            contextString = searchResults.map(item => {
                const record = item[0];
                const data = record?.data || record || {};
                return `Title: ${data.title || 'Untitled'}\nContent: ${data.content || ''}`;
            }).join('\n\n---\n\n');
        } else {
            contextString = "No relevant official documentation found in the database.";
        }

        e.data.vars.context = contextString;

    } catch (err) {
        console.log("Vector search failed: " + err);
        e.data.vars.context = "Error retrieving context from database.";
    }

    return e.data;
}

export default async function (e) {
    const data = e.record?.data || e.data;
    if (data && data.title && (!data.slug || data.slug.trim() === '')) {
        data.slug = $util.slugify(data.title);
    }
    return data;
}
